/**
 * Write public/_redirects so Cloudflare Workers Assets serves real 301s.
 * Node's scripts/serve.mjs reads the same map in scripts/redirects.mjs.
 */
import fs from 'node:fs';
import path from 'node:path';
import { PATH_REDIRECTS } from './redirects.mjs';

const lines = [
  '# Generated by scripts/write-cloudflare-redirects.mjs — do not hand-edit.',
];

for (const [from, to] of PATH_REDIRECTS) {
  if (from === to) continue;
  lines.push(`${from} ${to} 301`);
}

lines.push('/products/dota-2-cheats/* /products/mw4/:splat 301');

const file = path.join(process.cwd(), 'public', '_redirects');
fs.writeFileSync(file, `${lines.join('\n')}\n`, 'utf8');
console.log(`Wrote ${lines.length - 1} Cloudflare redirects → public/_redirects`);
